public class Main {
    static int arrangeCoins(int n) {
        long lo = 0, hi = n;
        while (lo <= hi) {
            long k = lo + (hi - lo) / 2;
            long total = k * (k + 1) / 2;             // closed-form triangular number
            if (total == n) return (int) k;
            if (total < n) lo = k + 1;                    // can afford more rows
            else hi = k - 1;                                // too many coins needed
        }
        return (int) hi;
    }
}

